if (argc == 2) {
    host = "localhost";
    port = argv[1];
} else if (argc == 3) {
    host = argv[1];
    port = argv[2];
} else {
    usage(1);
}

if (!isatty(STDIN_FILENO))
    errx(1, "not attached to a terminal");

raw_term();

if (strcmp(host, "--unix") == 0) {
    s = remote_connect_unix(port);
} else {
    s = remote_connect_inet(host, port);
}
